'use client';
import { useEffect } from 'react';
import posthog from 'posthog-js';
import { analyticsEnabled } from '../PostHogInit';
import { gaEvent } from '../ConsentPixel';

// OFERTA / checkout — przeniesiona z easygo-english.pl/oferta.html na TĘ domenę.
// To kluczowe: sesja Supabase zapisuje się osobno dla każdej domeny, więc strona
// płatności musi stać tam, gdzie użytkownik się loguje i gdzie wraca po zapłacie.
// Wcześniej oferta żyła na WordPressie i klient musiał logować się dwa razy.
//
// CSS/HTML/JS trzymane w base64, żeby cudzysłowy i znaki specjalne oryginału
// nie psuły składni — ten sam wzorzec co app/panel-lektora/page.js.

const CSS_B64 = "";
const BODY_B64 = "";
const SCRIPT_B64 = "";

function b64decode(b) {
  const bin = atob(b);
  const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
  return new TextDecoder('utf-8').decode(bytes);
}

// baner „Jak to działa”: dwa paski okładek przewijają się same (artykuły z bloga i ćwiczenia), pauza po najechaniu myszką
function fillFlowStrips() {
  const right = document.getElementById('ofFlowRight');
  const artTrack = document.getElementById('ofFlowArt');
  const exTrack = document.getElementById('ofFlowEx');
  if (!right || !artTrack || !exTrack || artTrack.children.length || !window.fetch) return;
  const URL_ = 'https://svjrdyxwqznbzxqeytdn.supabase.co';
  const KEY_ = 'sb_publishable_TNCq1UAMAvLO0Z5Mt8QOig_OvsxhhyJ';
  const headers = { apikey: KEY_, Authorization: 'Bearer ' + KEY_ };
  const esc = (t) => String(t == null ? '' : t).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const get = (q) => fetch(URL_ + '/rest/v1/' + q, { headers }).then((r) => (r.ok ? r.json() : [])).catch(() => []);
  function fill(track, items) {
    const html = items.map((it) =>
      '<a class="of-flow-card" href="' + esc(it.href) + '" aria-label="' + esc(it.title) + '">' +
      '<img src="' + esc(it.cover) + '" alt="" loading="lazy" decoding="async" onerror="this.style.visibility=\'hidden\'">' +
      '<span class="of-flow-ct">' + esc(it.title) + '</span></a>').join('');
    track.innerHTML = html + html; // dwa razy = przewijanie bez przerwy
    for (let k = items.length; k < track.children.length; k++) {
      track.children[k].setAttribute('aria-hidden', 'true');
      track.children[k].setAttribute('tabindex', '-1');
    }
    track.style.setProperty('--dur', items.length * 5 + 's');
  }
  Promise.all([
    get('articles?published=eq.true&cover_url=not.is.null&select=slug,title,cover_url&order=published_at.desc.nullslast&limit=8'),
    get('games?published=eq.true&cover_url=not.is.null&for_kids=is.false&select=slug,title,cover_url&order=published_at.desc.nullslast&limit=40'),
  ]).then(([arts, games]) => {
    if (!arts || arts.length < 2 || !games || games.length < 2) return;
    // z każdej serii tylko jedno ćwiczenie, żeby pasek był różnorodny
    const seen = new Set();
    const ex = [];
    for (const g of games) {
      const key = String(g.title).split(' (')[0].split(' - ')[0].trim().toLowerCase();
      if (seen.has(key)) continue;
      seen.add(key);
      ex.push({ href: '/cwiczenie/' + encodeURIComponent(g.slug), title: g.title, cover: g.cover_url });
      if (ex.length >= 10) break;
    }
    fill(artTrack, arts.map((a) => ({ href: '/nauka?a=' + encodeURIComponent(a.slug), title: String(a.title).split(' — ')[0], cover: a.cover_url })));
    fill(exTrack, ex);
    right.classList.remove('of-flow-empty');
  });
}

export default function Oferta() {
  useEffect(() => {
    // zakładki w sekcji „Co jeszcze warto wiedzieć?” (rejestrowane zawsze, także przy ponownym montażu)
    function onTab(e) {
      const tab = e.target && e.target.closest ? e.target.closest('.of-tab') : null;
      if (!tab) return;
      const k = tab.getAttribute('data-tab');
      document.querySelectorAll('.of-tab').forEach((t) => t.classList.toggle('on', t === tab));
      document.querySelectorAll('.of-panel').forEach((p) => { p.hidden = p.getAttribute('data-panel') !== k; });
    }
    document.addEventListener('click', onTab);

    if (document.getElementById('eg-oferta-style')) {
      fillFlowStrips();
      return () => document.removeEventListener('click', onTab);
    }

    const style = document.createElement('style');
    style.id = 'eg-oferta-style';
    style.textContent = b64decode(CSS_B64);
    document.head.appendChild(style);

    const mount = document.getElementById('oferta-mount');
    if (mount) mount.innerHTML = b64decode(BODY_B64);

    // plakietka „od 1 grudnia” przy maturze znika po starcie (1 grudnia 2026, 15:00 czasu polskiego)
    if (Date.now() >= Date.UTC(2026, 11, 1, 14, 0, 0)) {
      const soon = document.getElementById('ofMaturaSoon');
      if (soon) soon.remove();
      const tabNote = document.getElementById('ofMaturaTabNote');
      if (tabNote) tabNote.remove();
    }

    fillFlowStrips();

    function trackCheckout(e) {
      const button = e.target && e.target.closest ? e.target.closest('#buyInd,#buyLek,#resumeBtn') : null;
      if (!button) return;
      let plan = button.id === 'buyLek' ? 'teacher' : 'individual';
      if (button.id === 'resumeBtn') {
        try {
          const savedPlan = (localStorage.getItem('eg_plan_choice') || '').split(',')[0];
          if (savedPlan === 'teacher' || savedPlan === 'individual') plan = savedPlan;
        } catch (err) {}
      }
      const yearly = document.getElementById('btnYearly');
      const seats = document.getElementById('seatsVal');
      const props = {
        plan,
        billing_cycle: yearly && yearly.classList.contains('active') ? 'yearly' : 'monthly',
        seats: plan === 'teacher' && seats ? Number(seats.textContent) : 1,
      };
      gaEvent('begin_checkout', props);
      if (analyticsEnabled) posthog.capture('checkout_started', props);
    }
    document.addEventListener('click', trackCheckout);


    // Supabase z CDN, potem oryginalny skrypt oferty
    const sdk = document.createElement('script');
    sdk.src = 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2';
    sdk.onload = () => {
      const s = document.createElement('script');
      s.textContent = b64decode(SCRIPT_B64);
      document.body.appendChild(s);
    };
    document.body.appendChild(sdk);

    return () => {
      document.removeEventListener('click', trackCheckout);
      document.removeEventListener('click', onTab);
    };
  }, []);

  return <div id="oferta-mount" />;
}
